import os,runpy,sys
cands=[os.path.abspath('.')]
for k in ('ISOTONE_REPO_ROOT','CLAUDE_PROJECT_DIR','PWD'):
 v=os.environ.get(k,'').strip()
 if v: cands.append(os.path.abspath(v))
target=''
for p in cands:
 while p!=os.path.dirname(p) and not os.path.isfile(os.path.join(p,'scripts','lsp-mcp-server.py')): p=os.path.dirname(p)
 t=os.path.join(p,'scripts','lsp-mcp-server.py')
 if os.path.isfile(t): target=t; break
if not target: print('isotone-lsp: could not locate scripts/lsp-mcp-server.py from '+os.getcwd(), file=sys.stderr); sys.exit(1)
sys.argv=[target]; runpy.run_path(target, run_name='__main__')
